t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def solve(gi):
    gi=np.array(gi); H_,W_=gi.shape
    pos=np.argwhere(gi==8)
    mr=min(pos[:,0]); mc=min(pos[:,1])
    oh=max(pos[:,0])-mr+1; ow=max(pos[:,1])-mc+1
    base=np.zeros((oh,ow))
    Ts={'id':base.copy(),'fplr':np.fliplr(base),'fupd':np.flipud(base),
        'rot':np.rot90(base),'lr':np.fliplr(np.rot90(base)),'ud':np.rot90(base[::-1,:]),'both':np.fliplr(np.flipud(base))}
    res={}
    for name,t in Ts.items():
        h,w=t.shape
        hits=[(r0,c0) for r0 in range(H_-h+1) for c0 in range(W_-w+1) if (t==gi[r0:r0+h,c0:c0+w]).all()]
        if hits: res[name]=(hits,(mr,mr+oh-1,mc,mc+ow-1),(r0,r0+h-1,c0,c0+w-1))
    return res
for i in range(1,5):
    res=solve(G[f'Demo pair {i} input'])
    print('demo',i,{k:v[0] for k,v in res.items()})

